#pragma once
static void checkCatalyticV2(App& app,const std::string& dir){
 using namespace studio::catalytic;auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("catalytic v2: "+why);};int cases=0;
 for(int n=0;n<2;++n)for(int format=0;format<4;++format)for(bool excited:{false,true})for(bool collapsed:{false,true}){
    CatalyticMetal cfg;cfg.numerals=n;cfg.format=format;cfg.excited=excited;cfg.collapsed=collapsed;Session sample;sample.doc.setDefaultFont("Arial");sample.doc.setDefaultBondLength(22);auto id=cfg.apply(sample.doc,kInvalidObjectId,Vec2());auto text=sample.doc.atomLabel(id);
    require(text.find(n?"2":"II")!=std::string::npos,"numeral style reaches real label: "+text+" format="+std::to_string(format)+" compact="+std::to_string(collapsed));require((text.find('*')!=std::string::npos)==excited,"excited state independent of oxidation");
    auto parsed=CatalyticMetal::read(sample.doc,id);require(parsed.numerals==n&&parsed.format==format&&parsed.excited==excited,"settings remembered");
    if(!collapsed)require(CatalyticMetal::fold(sample.doc,id,false),"right-click collapse model");require(sample.doc.stats().aliveAtoms==1,"compact one visible anchor");
    require(CatalyticMetal::fold(sample.doc,id,true),"expand compact fragment");require(sample.doc.stats().aliveAtoms==4&&sample.doc.stats().aliveBonds==3&&sample.doc.atoms().alive(id)->element==46,"real metal and three ligands restored at same anchor");
    auto runs=studioatom::runs(sample.doc,id);bool star=false;for(auto r:runs)if(r.utf8.find('*')!=std::string::npos)star=(r.flags&kSuperscript)!=0;require(!excited||star,"star remains superscript after expansion");++cases;
 }
 Session demo;demo.doc.setDefaultFont("Arial");demo.doc.setDefaultBondLength(22);studioio::Page pg;pg.x=pg.y=0;pg.width=650;pg.height=650;pg.store(demo.doc);CatalyticMetal cfg;cfg.excited=true;std::vector<ObjectId> nodes;for(int i=0;i<6;++i)nodes.push_back(cfg.apply(demo.doc,kInvalidObjectId,Vec2(i*70,0)));std::vector<ObjectRef> made;
 require(arrange(demo.doc,nodes,Vec2(300,300),185,140,true,&made,true,.3).ok(),"inherit rotated ellipse");
 for(auto ref:made){arrows::ArrowParams p;bool valid=false;arrows::readArrow(demo.doc,ref.id,&p,&valid);require(valid&&p.route.size()>16,"ellipse retains smooth route");for(auto q:arrows::routedPoints(p)){auto v=q-Vec2(300,300);double x=v.x*std::cos(.3)+v.y*std::sin(.3),y=-v.x*std::sin(.3)+v.y*std::cos(.3);require(std::abs(x*x/(185*185)+y*y/(140*140)-1)<1e-8,"all spans on exact same inherited ellipse");}}
 // Repeated layout, folding, and whole-object translation never consume the curve.
 auto pathLength=[&](const Document& d,ObjectId id){arrows::ArrowParams p;bool ok=false;arrows::readArrow(d,id,&p,&ok);double total=0;auto pts=arrows::routedPoints(p);for(size_t i=1;i<pts.size();++i)total+=length(pts[i]-pts[i-1]);return total;};
 std::map<ObjectId,double> lengths;for(auto r:made)lengths[r.id]=pathLength(demo.doc,r.id);
 for(int repeat=0;repeat<12;++repeat){require(update(demo.doc).ok(),"repeat update");for(auto r:made)require(std::abs(pathLength(demo.doc,r.id)-lengths[r.id])<1e-6,"refresh keeps arrow length");}
 for(int repeat=0;repeat<4;++repeat){require(integration::translateDocumentObjects(demo.doc,demo.all(),Vec2(23,-17)).ok(),"move whole cycle");require(update(demo.doc).ok(),"follow whole cycle");for(auto r:made)require(std::abs(pathLength(demo.doc,r.id)-lengths[r.id])<1e-5,"whole drag preserves curve length");}
 for(auto id:nodes)require(CatalyticMetal::fold(demo.doc,id,false),"collapse cycle node");require(update(demo.doc).ok(),"follow compact labels");
 std::map<ObjectId,double> compact;for(auto r:made){compact[r.id]=pathLength(demo.doc,r.id);require(compact[r.id]>15,"collapsed label keeps visible shaft");}
 for(int repeat=0;repeat<8;++repeat){require(update(demo.doc).ok(),"repeat compact update");for(auto r:made)require(std::abs(pathLength(demo.doc,r.id)-compact[r.id])<1e-6,"compact preview stable");}
 for(auto id:nodes)require(CatalyticMetal::fold(demo.doc,id,true),"expand cycle node");require(update(demo.doc).ok(),"expanded curve");
 // Ordinary crossing arrows retain their endpoints; only the later path changes.
 Document crossing;auto a=arrows::resolvePreset(58,Vec2(40,130),Vec2(230,130),.6);a.arcSagitta=-65;ObjectId first,later;arrows::addArrow(crossing,a,.6,&first);auto b=arrows::resolvePreset(58,Vec2(130,30),Vec2(130,230),.6);b.arcSagitta=65;arrows::addArrow(crossing,b,.6,&later);arrows::ArrowParams old;bool valid=false;arrows::readArrow(crossing,first,&old,&valid);auto encoded=arrows::encodeArrowParams(old);require(studio::arrow_crossings::update(crossing).ok(),"crossing operation");arrows::ArrowParams smoothed;arrows::readArrow(crossing,later,&smoothed,&valid);require(smoothed.route.size()>60&&length(smoothed.begin-b.begin)<1e-8&&length(smoothed.end-b.end)<1e-8,"newer crossing arrow becomes editable S curve with fixed endpoints");arrows::readArrow(crossing,first,&old,&valid);require(arrows::encodeArrowParams(old)==encoded,"earlier arrow unchanged");
 for(const auto& path:{std::string("cdxml"),std::string("r62doc")}){auto name=dir+"/smooth-catalytic-demo."+path;require(demo.save(name,path=="cdxml").ok(),"save "+path);Session reopened;require(reopened.open(name).ok(),"reopen "+path);int count=0;for(const auto& x:reopened.doc.atoms().records())if(x.isAlive()&&reopened.doc.extensions(ObjectRef(ObjectKind::Atom,x.id)).findValue(CatalyticMetal::attr("Metal"))){require(CatalyticMetal::read(reopened.doc,x.id).excited,"excited state survives file");++count;}require(count==6,"all six metal settings survive");int paths=0;for(const auto& arrow:reopened.doc.arrows().records())if(arrow.isAlive()&&reopened.doc.extensions(ObjectRef(ObjectKind::Arrow,arrow.id)).findValue("pst.attr.MoleculeStudioCatalyticPath"))++paths;require(paths==6,"unclipped source paths survive file");}
 CycleFields dialog;dialog.cycle=true;dialog.values={"6","185","140"};dialog.metal=cfg;require(dialog.rebuild()&&dialog.cyclePreview&&dialog.metalPreview,"both live previews use real structures");dialog.values[1]="bad";require(!dialog.rebuild(),"invalid preview input rejected");
 // Independent preview configuration retains the other nodes.
 CycleFields individual;individual.cycle=true;individual.values={"4","107.096530","74.613799"};individual.fixedSize=true;require(individual.rebuild(),"initial individual preview");individual.nodeMetals[1].element="Ni";individual.nodeMetals[1].oxidation="III";individual.nodeMetals[1].collapsed=true;individual.editedNodes.insert(1);require(individual.rebuild(),"individual edit preview");for(size_t i=0;i<4;++i)require(CatalyticMetal::read(individual.cyclePreview->source->doc,individual.previewNodes[i]).element==(i==1?"Ni":"Pd"),"only selected complex changed");
 // Exercise the actual selection handle gesture on a native oval.
 app.s.cancel();app.s.doc=Document();app.s.history.clear();graphics::ShapeParams shape;shape.form=graphics::ShapeForm::Oval;shape.frame.centre=Vec2(100,100);shape.frame.axisU=Vec2(40,0);shape.frame.axisV=Vec2(0,25);ObjectId oval;require(graphics::addShape(app.s.doc,shape,.6,&oval).ok(),"insert oval");app.s.selected={ObjectRef(ObjectKind::Arrow,oval)};app.s.activateCommand("chooseSelectionTool_Marquee");app.s.refresh();auto handles=app.selectionHandlePoints();require(handles.size()==9,"oval exposes resize handles");auto start=app.s.view().toDevice(handles[4]);require(app.beginSelectionTransform(start,0),"begin oval width resize");app.finishSelectionTransform(start+Vec2(40,0),0);bool validShape=false;graphics::readShape(app.s.doc,oval,&shape,&validShape);require(validShape&&length(shape.frame.axisU)>40&&std::abs(length(shape.frame.axisV)-25)<1e-6,"side handle changes width only");require(app.s.undo().ok(),"undo oval resize");graphics::readShape(app.s.doc,oval,&shape,&validShape);require(std::abs(length(shape.frame.axisU)-40)<1e-6,"undo restores oval width");
 app.execute(Button("test.transition","过渡态","bracket","@transitionState"));require(app.s.selected.size()==1&&app.s.selected[0].kind==ObjectKind::Bracket,"transition state is one bracket object");graphics::BracketParams bracket;bool validBracket=false;graphics::readBracket(app.s.doc,app.s.selected[0].id,&bracket,&validBracket);require(validBracket&&bracket.paired()&&bracket.labels.size()==1&&bracket.labels[0].text=="‡","paired square bracket includes double dagger");
 app.s.cancel();app.s.doc=demo.doc;app.s.history.clear();app.s.selected.clear();app.s.refresh();app.s.fit();app.invalidate();app.screenshot(dir+"/smooth-catalytic-demo.png",false,false);
 std::ofstream(dir+"/catalytic-v2-checks.json")<<"{\"metal_format_cases\":"<<cases<<",\"real_fragment_fold_expand\":true,\"excited_state\":true,\"exact_inherited_ellipse\":true,\"dual_previews\":true,\"later_arrow_S_transition\":true,\"earlier_arrow_unchanged\":true,\"native_and_cdxml\":true}";
}

